pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor, uint256 t) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1 ether, 100 ether);
        t = bound(t, 0, block.timestamp - 1); // past unlock time

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);

        // Rule: funds deposited with any unlock time are locked at least until
        // the current block timestamp, so Collect must fail in the same block.
        bool ok;
        vm.prank(actor);
        try c.Collect(amount) { ok = true; } catch { ok = false; }
        assertTrue(!ok, "Collect succeeded in same block as Put with past unlock time");
    }
}

