pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor, uint256 t, uint256 t0, uint256 b) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1 ether, 1000 ether);
        t0 = bound(t0, 2, 10_000 days); // time of the Put
        t = bound(t, 0, t0 - 1);        // past unlock time
        b = bound(b, t + 1, t0);        // a time strictly after t but not after the Put time

        vm.warp(t0);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);

        vm.warp(b);
        vm.prank(actor);
        try c.Collect(amount) {
            assertTrue(false, "Collect succeeded before unlock time");
        } catch {
            assertTrue(true);
        }
    }
}

