pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor, uint256 pastUnlock, uint256 collectAmt) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1 ether, 1000 ether);
        collectAmt = bound(collectAmt, 1 ether, amount);
        // pastUnlock strictly before current block time
        pastUnlock = bound(pastUnlock, 0, block.timestamp - 1);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(pastUnlock);

        vm.prank(actor);
        bool ok;
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        // Same-block Collect after a Put with a past unlock time must fail:
        // funds stay locked until at least the current block time.
        assertTrue(!ok);
    }
}

