contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor, uint256 t) public {
        vm.assume(actor != address(c) && actor != address(0));
        vm.warp(1000);
        amount = bound(amount, 1 ether, 1e30);
        t = bound(t, 0, 999); // strictly in the past relative to warped block time

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);

        vm.prank(actor);
        bool ok;
        try c.Collect(amount) { ok = true; } catch { ok = false; }

        // Rule: funds deposited in this block stay locked this block; a same-block
        // Collect of the full (>= MinSum) balance must fail in every admissible case.
        assertTrue(!ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0));
        vm.deal(actor, amount * 2);

        // First Put: should always succeed.
        vm.prank(actor);
        c.Put{value: amount}(0);

        // General rule: a second Put from any account must still succeed
        // (the reentrancy lock is released after each call).
        bool secondOk;
        vm.prank(actor);
        try c.Put{value: amount}(0) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        assertTrue(secondOk);
    }
}

