pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, address first, address second) public {
        vm.assume(first != address(0) && second != address(0) && first != second);
        vm.assume(first != address(c) && second != address(c));
        amount = bound(amount, 0, 1e30);

        vm.deal(first, amount);
        vm.prank(first);
        c.Put{value: amount}(0);

        vm.deal(second, amount);
        vm.prank(second);
        bool ok;
        try c.Put{value: amount, gas: 200000}(0) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok, "Put from a fresh address must succeed after any prior Put");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}
    function test(uint amount) public {
        require(amount >= 1 ether, "below min");
        require(address(this).balance >= amount, "insufficient");
        c.Put{value: amount}(0);
        uint before = c.History_length();
        c.Collect(amount);
        uint after_ = c.History_length();
        assert(after_ == before + 1);
    }
}

contract InvMutTest {
    C c;
    uint tAmount;

    constructor(C _c) { c = _c; }

    function run(uint unlockTime) public {
        require(address(this).balance >= 2 ether);
        require(unlockTime < block.timestamp);
        tAmount = address(this).balance / 2;
        c.Put{value: tAmount}(unlockTime);
        c.Collect(tAmount);
        assert(c.Acc(address(this)).balance == tAmount);
    }

    receive() external payable {
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", tAmount));
        ok;
    }

    fallback() external payable {}
}

contract InvMutTest {
    C c;
    uint lastAmount;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        require(amount >= c.MinSum());
        lastAmount = amount;
        c.Put{value: amount}(0);
        bool reverted;
        try c.Collect(amount) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {
        try c.Collect(lastAmount) {} catch {}
    }
}
